"""Build q_analysis.md only from completed preserved Stage 4 measurements."""
from pathlib import Path
import csv,json,sys,hashlib,platform,os
os.environ.setdefault("MPLCONFIGDIR", "/tmp/mds-matplotlib")
os.environ.setdefault("XDG_CACHE_HOME", "/tmp/mds-cache")
import numpy as np
import matplotlib
import PIL
ROOT=Path(__file__).resolve().parents[1]
def main():
 out=ROOT/'stage4/results'
 selection=json.loads((ROOT/'stage4/selection.json').read_text())
 rows=list(csv.DictReader((out/'metrics.csv').open()))
 stability=json.loads((out/'neighborhoods.json').read_text())
 pca=json.loads((out/'pca_validation.json').read_text())
 assert len(rows)==18 and len(pca)==6 and all(r['passed'] for r in pca)
 s=['# Investigation of Minkowski distances using classical MDS','', '## 1. Introduction and research questions','', 'How does q change distance ordering, local neighborhoods, Euclidean representability, and low-dimensional reconstruction? We compare exactly three feature-only UCI datasets without scaling. Selection used documented properties and feasibility, not q-dependent outcomes. Targets are excluded throughout.','', '## 2. Dataset selection record','',f"Final selection was recorded at {selection['recorded_at_utc']} before the runner launched any q experiment; the runner preserved a copy as [selection_used.json](stage4/results/selection_used.json). The same SHA-256-pinned matrix and original row/feature ordering were used for every q and dimension. No replacements occurred.",'',selection['rationale'],'']
 for ds in selection['datasets']:
  slug=ds['slug']
  s += [f"### {ds['title']} — UCI {ds['uci_id']}",'',f"Official URL: {ds['url']}. Source: `{ds['archive']}` containing `{ds['source_files'][0]}`. Final slug: `{slug}`; dimensions **{ds['observations']} × {ds['numeric_features']}**. [Final numeric matrix]({ds['matrix']}). Rows are individual wine samples, wheat kernels, or glass samples, respectively; source files have no header, so the first source row is preserved as an observation.",'',f"Features, in order: {', '.join(ds['feature_names'])}. Excluded: {ds['excluded']}. {ds['missing']}",'']
 s += ['Wine and Glass feature roles and missingness were read from the archive .names files. Seeds was checked against its preserved official page and API additional_info.variable_info: seven geometric features, no missingness. The API num_features=0 and empty variable-role entries are incomplete metadata; they were not interpreted as absence of features. The eighth raw column is an excluded variety code, not an eighth measurement. No class information was used in experiments.','', '## 3. Methodology','', 'Distances are D_ij=(sum_r |x_ir-x_jr|^q)^(1/q), or max_r |x_ir-x_jr| for q=inf. All six q values (1, 1.5, 2, 3, 4, inf) use the existing mds.py CLI, separately in dimensions 2 and 3: 36 subprocess executions. No high-level MDS routine is used.','', 'Classical STRAIN constructs G=-0.5 H(D∘D)H, H=I-11ᵀ/n, implemented by equivalent row/column means. numpy.linalg.eigh supplies symmetric eigenpairs; sorted eigenvalues are clipped below zero for Y=V_k sqrt(max(lambda_k,0)). mds.py was not modified. The negative tolerance is tau=100*eps*n*max(1,max_i|lambda_i|), with float64 eps. Meaningful negatives satisfy lambda<-tau; tiny negative values are rounding noise, but every negative value is clipped in construction.','', 'Metrics: N−=count(lambda<-tau); M−=sum_{lambda<-tau}|lambda|. Positive mass capture P_k=sum_{i<=k}max(lambda_i,0)/sum_i max(lambda_i,0). Normalized distance error E_k=sqrt(sum_{i<j}(||y_i-y_j||₂-D_ij)²/sum_{i<j}D_ij²). The same formula normalizes by original distance energy for each q, enabling comparison despite overall distance magnitude changes; it does not remove feature-unit effects. Positive mass includes tiny positive eigenvalues consistently.','', 'Neighborhood agreement is |N_q(i)∩N_2(i)|/10 for 10 nearest neighbors, self excluded. Exact ties are resolved by original row order using stable sorting. Most/least stable rows maximize/minimize mean overlap across the five nonbaseline q values. All row references below are one-based final-matrix observation rows, excluding the CSV header. Baseline overlap is identically 1.','', 'No standardization, normalization, or rescaling of feature values is performed. Temporary per-pair norm evaluation in mds.py only stabilizes the exact Minkowski formula numerically.','', '## 4. Numerical results','', '| Dataset | q | N− | M− | P₂ | P₃ | E₂ | E₃ | Mean 10-NN overlap |','|---|---|---:|---:|---:|---:|---:|---:|---:|']
 for r in rows:
  s.append('| '+ ' | '.join([r['dataset'],r['q'],r['negative_count']]+[f"{float(r[k]):.8g}" for k in ('negative_mass','positive_mass_2d','positive_mass_3d','normalized_error_2d','normalized_error_3d','mean_10nn_overlap')])+' |')
 s += ['', 'Full-precision values and per-run tolerance are in [metrics.csv](stage4/results/metrics.csv). Every CLI run passed distance symmetry/nonnegativity/finiteness/zero diagonal, Gram symmetry and explicit double-centering equivalence, shape, centering, finite coordinates, eigenvalue ordering/clipping, eigenpair residual, orthonormality, CSV round trip, and PNG decoding checks. All 36 diagnostic JSONs are preserved.','', '## 5. Neighborhood stability and distance-order changes','']
 for ds in selection['datasets']:
  slug=ds['slug']; n=stability[slug]; a=np.array(n['mean_nonbaseline_overlap']); local=[r for r in rows if r['dataset']==slug and r['q']!='2']; worst=min(local,key=lambda r:float(r['mean_10nn_overlap']))
  s += [f"**{ds['title']}:** across nonbaseline q, per-row mean overlap ranges from {a.min():.6f} to {a.max():.6f}. Most stable rows: {n['most_stable_rows_1based']}; least stable rows: {n['least_stable_rows_1based']}. Lowest dataset mean agreement occurs at q={worst['q']} ({float(worst['mean_10nn_overlap']):.6f}). These row lists include all exact ties, without target-based selection.",'']
 s += ['Per-observation overlaps at every q are preserved in [neighborhoods.json](stage4/results/neighborhoods.json). Subunit agreement establishes changes in nearest-neighbor membership under the specified tie rule; it is not explained by multiplying all distances by a common constant. Exact and near ties can influence membership, so this statistic does not establish a complete ordering of all pairs.','', '## 6. Dataset-specific findings','']
 for ds in selection['datasets']:
  slug=ds['slug']; local=[r for r in rows if r['dataset']==slug]; negative=max(local,key=lambda r:float(r['negative_mass'])); err2=min(local,key=lambda r:float(r['normalized_error_2d'])); err3=min(local,key=lambda r:float(r['normalized_error_3d'])); n=stability[slug]; shares=np.array(n['mean_squared_difference_share']); order=np.argsort(shares)[::-1]
  s += [f"### {ds['title']}",'',f"Largest absolute negative mass occurs at q={negative['q']} (M−={float(negative['negative_mass']):.8g}); this comparison is within this dataset's native units. Lowest E₂ is at q={err2['q']} ({float(err2['normalized_error_2d']):.6g}), lowest E₃ at q={err3['q']} ({float(err3['normalized_error_3d']):.6g}). Across q, P₂ ranges {min(float(r['positive_mass_2d']) for r in local):.6f}–{max(float(r['positive_mass_2d']) for r in local):.6f}; P₃ ranges {min(float(r['positive_mass_3d']) for r in local):.6f}–{max(float(r['positive_mass_3d']) for r in local):.6f}.",'', 'Measured native-unit squared-distance contributions (mean pairwise feature squared difference divided by their sum) are '+', '.join(f"{n['features'][i]} {shares[i]:.2%}" for i in order[:3])+'. These quantify dominance at q=2; they do not prove identical dominance for all q.','']
  s += [f"![{ds['title']} classical MDS q=1](stage4/results/{slug}_mds_q1_2D.png)",f"![{ds['title']} classical MDS q=2](stage4/results/{slug}_mds_q2_2D.png)",f"![{ds['title']} classical MDS q=infinity](stage4/results/{slug}_mds_qinf_2D.png)",'', 'These native 2D views support inspection of concentration and spread. Point style/order and panel size are fixed. Each panel has independently determined axes and automatic axis limits; orientation, handedness, and plotted span are not shared. Apparent rotations/reflections are not evidence of neighborhood changes; geometric conclusions above use invariant numerical measures.','']
 s += ['## 7. Cross-dataset comparison','', 'Mathematically, increasing q makes the largest coordinate differences relatively more important, and each fixed pair distance is nonincreasing with q. Neither fact implies preserved relative distance ordering. The q=2 Gram matrix is positive semidefinite in exact arithmetic; non-Euclidean Minkowski distances need not admit an exact Euclidean embedding. Meaningful negative mass measures the spectral part discarded by the PSD approximation, not distance RMSE itself.','', 'Empirically, the table allows q effects to be separated from overall units through normalized error and overlap. Absolute negative masses should not be ranked across datasets as a scale-free measure. The best normalized distance q need not be 2, and more dimensions need not monotonically improve distance error for non-Euclidean inputs: STRAIN optimizes Gram approximation, not distance stress. Claims of feature dominance are supported by measured contributions above, rather than labels or visual clusters.','', '## 8. q = 2 centered PCA validation','', 'Independent NumPy SVD of X-column_means(X), with no scaling, supplies PCA coordinates. Compare Euclidean distances from the saved MDS embeddings to those PCA configurations.','', '| Dataset | Dimensions | Maximum absolute pairwise-distance discrepancy | Tolerance | Passed |','|---|---:|---:|---:|---|']
 for r in pca:
  s.append(f"| {r['dataset']} | {r['dimensions']} | {r['pairwise_distance_max_abs']:.9g} | {r['tolerance']:.9g} | {r['passed']} |")
 s += ['', 'All six comparisons confirm the expected equivalence within scale-aware float64 tolerance. Coordinates are not required to agree elementwise. PCA coordinates were never inputs to MDS. [Full validation](stage4/results/pca_validation.json).','', '## 9. Feature-unit sensitivity and limitations','', 'Wine mixes chemical assays with markedly different numerical ranges. Proline and magnesium can dominate native-unit distances; the measured shares above test this claim. The preserved UCI names do not specify physical units for every assay, so no unsupported unit conversion is inferred. Comparing q here is meaningful for this exact recorded representation, not as a unit-invariant chemical geometry.','', 'Seeds mixes area, perimeter, lengths, compactness=4*pi*A/P², and an asymmetry coefficient. Length/area and dimensionless shape quantities cannot be physically added without a unit convention. The official metadata does not specify all absolute physical units. Correlated size features can repeatedly count size; native-unit area and shape contributions above indicate the degree, without proving causal explanations.','', 'Glass combines dimensionless refractive index with oxide weight percentages. RI has very small variation, while oxide composition varies by percentage points and includes genuine zeros. A percentage sum constraint also induces dependence. Its largely common oxide units make q contrasts interpretable within composition, but inclusion of RI and the choice of percentage units still prevent unit-invariant conclusions.','', 'None of the three was rescaled as required. Changing measurement units could change all findings, including neighborhood identities. Observational association is not causation. No labels were used; no claim about supervised class separation is made. The neighborhood result is conditional on k=10 and deterministic tie handling; there was no sensitivity sweep over k. Dense storage is quadratic and EVD cubic, restricting scalability.','', '## 10. Conclusions','', 'Changing q changes the balance of coordinate contributions and can change neighborhoods. The measured negative masses, positive spectral capture, and normalized errors distinguish representation loss from roundoff. Euclidean q=2 uniquely supplies the general centered-PCA equivalence; the six numerical tests confirm it here. Dataset-specific numerical results should be interpreted in native units rather than used to recommend a universally optimal q.','', '## 11. Reproducibility instructions','', f"Versions: Python {platform.python_version()}, NumPy {np.__version__}, Matplotlib {matplotlib.__version__}, Pillow {PIL.__version__}. No random procedures are used. New AI-written preparation, experiment, and report scripts are preserved; existing mds.py and earlier tracked files were not modified.",'', 'From the repository root, with these package versions installed:','', '```sh','python3 stage4/prepare_data.py','OPENBLAS_NUM_THREADS=1 OMP_NUM_THREADS=1 python3 stage4/run_experiments.py','python3 stage4/build_report.py','```','', 'The preserved official ZIPs allow offline preparation. prepare_data.py reconstructs headers, excludes metadata, validates finite matrices, and records selection before any experiments. The runner validates matrix hashes before computing distances. To repeat a single CLI run:','', '```sh','python3 mds.py --input data/stage4/wine.csv --q 1.5 --dimensions 3 --output-dir stage4/results','```','', 'Sources: official UCI Wine ZIP https://archive.ics.uci.edu/static/public/109/wine.zip ; Seeds ZIP https://archive.ics.uci.edu/static/public/236/seeds.zip ; Glass ZIP https://archive.ics.uci.edu/static/public/42/glass+identification.zip . Documentation is preserved under data/stage4/sources; source and matrix hashes are in stage4/selection.json. Preserve existing selection records before intentionally regenerating them for a new run.','', 'Outputs: three numeric matrices; 36 PNGs, 36 embedding CSVs, 36 diagnostic JSONs, 36 CLI logs under stage4/results; metrics.csv, neighborhoods.json, pca_validation.json, selection_used.json; selection.json, preparation/experiment/report scripts, protected_hashes.json and this report. The nine figures above are supporting evidence; all 36 plots remain available. Nothing is committed or pushed by these scripts.']
 idx=s.index('## 8. q = 2 centered PCA validation')
 s[idx:idx]=['Across all three datasets, q=1 has the largest absolute negative mass, q=2 has zero meaningful negative eigenvalues, and every nonbaseline q changes some 10-NN neighborhoods. Wine is most stable in aggregate (nonbaseline mean agreements 0.9247–0.9803), Seeds intermediate (0.8462–0.9433), and Glass reaches the lowest agreement at infinity (0.7972). These are empirical outcomes, not general norm theorems.', '', 'Wine and Seeds both minimize normalized 2D and 3D distance error at q=2. Glass instead minimizes both at q=3 (E₂=0.246236, E₃=0.124509), despite its genuine negative spectrum. Thus positive semidefiniteness does not guarantee the best low-dimensional relative distance error across different distance definitions. Wine captures over 94% positive mass in 2D for every q; Glass captures only about 55–74%. Proline accounts for 99.77% of Wine squared-distance energy, while the leading Glass features magnesium and calcium contribute 33.00% and 32.13%. This supports the tentative explanation that Wine geometry is dominated by one native-unit measurement, whereas Glass has more competing geometric directions. Seeds is also scale-imbalanced (area 65.06%) but its asymmetry coefficient contributes 17.37%, more than perimeter (13.11%); a purely size-only explanation would miss that evidence.', '', 'The nine figures show raw independently oriented configurations, so only numerical comparisons establish changes in local membership. No visual claim of class structure is made. In particular, orientation differences and changes in axis scale should not be interpreted as distance-order reversals.', '']
 (ROOT/'q_analysis.md').write_text('\n'.join(s)+'\n')
 protected=json.loads((ROOT/'stage4/protected_hashes.json').read_text())
 assert all(hashlib.sha256((ROOT/p).read_bytes()).hexdigest()==v for p,v in protected.items())
 import re
 links=re.findall(r'\]\(([^)]+)\)',(ROOT/'q_analysis.md').read_text())
 assert all((ROOT/p).is_file() for p in links if not p.startswith('http'))
 checks={'exactly_three_datasets':len(selection['datasets'])==3,'36_cli_runs':len(list(out.glob('*D.log')))==36,'36_embeddings':len(list(out.glob('*D.csv')))==36,'36_passed_diagnostics':sum(json.loads(p.read_text())['all_checks_passed'] for p in out.glob('*_diagnostics.json'))==36,'18_metric_rows':len(rows)==18,'six_pca_comparisons':len(pca)==6,'report_links_exist':True,'earlier_tracked_files_unchanged':True,'selection_before_runs':(out/'selection_used.json').stat().st_mtime < min(p.stat().st_mtime for p in out.glob('*D.log'))}
 assert all(checks.values()),checks
 (ROOT/'stage4/verification.json').write_text(json.dumps(checks,indent=2)+'\n')
 print(json.dumps(checks,indent=2))
if __name__=='__main__': main()
